SELECT l.APPLICATION_ID, a.APPLICATION_NO, l.LOAN_ID, l.LOAN_ACCOUNT_NO, a.FINANCIER_ID, f.ORG_NAME_AR FINANCIER_NAME_AR, 'DELINQUENCY' REPORT_EVENT_TYPE, d.START_DATE EVENT_DATE, TO_CHAR(d.DAYS_PAST_DUE) EVENT_VALUE, d.COLLECTION_ACTION_AR EVENT_DETAILS_AR FROM MFF_DELINQUENCIES d JOIN MFF_LOANS l ON l.LOAN_ID=d.LOAN_ID JOIN MFF_APPLICATIONS a ON a.APPLICATION_ID=l.APPLICATION_ID JOIN MFF_ORGANIZATIONS f ON f.ORG_ID=a.FINANCIER_ID UNION ALL SELECT l.APPLICATION_ID,a.APPLICATION_NO,l.LOAN_ID,l.LOAN_ACCOUNT_NO,a.FINANCIER_ID,f.ORG_NAME_AR, 'LEGAL_ACTION',la.ACTION_DATE,la.STATUS,la.OUTCOME_AR FROM MFF_LEGAL_ACTIONS la JOIN MFF_LOANS l ON l.LOAN_ID=la.LOAN_ID JOIN MFF_APPLICATIONS a ON a.APPLICATION_ID=l.APPLICATION_ID JOIN MFF_ORGANIZATIONS f ON f.ORG_ID=a.FINANCIER_ID UNION ALL SELECT l.APPLICATION_ID,a.APPLICATION_NO,l.LOAN_ID,l.LOAN_ACCOUNT_NO,a.FINANCIER_ID,f.ORG_NAME_AR, 'EARLY_SETTLEMENT',es.REQUEST_DATE,es.SETTLEMENT_TYPE,es.NOTES_AR FROM MFF_EARLY_SETTLEMENTS es JOIN MFF_LOANS l ON l.LOAN_ID=es.LOAN_ID JOIN MFF_APPLICATIONS a ON a.APPLICATION_ID=l.APPLICATION_ID JOIN MFF_ORGANIZATIONS f ON f.ORG_ID=a.FINANCIER_ID UNION ALL SELECT l.APPLICATION_ID,a.APPLICATION_NO,l.LOAN_ID,l.LOAN_ACCOUNT_NO,a.FINANCIER_ID,f.ORG_NAME_AR, e.EVENT_TYPE_CODE,e.EVENT_DATE,e.STATUS,e.DETAILS_AR FROM MFF_LOAN_EVENTS e JOIN MFF_LOANS l ON l.LOAN_ID=e.LOAN_ID JOIN MFF_APPLICATIONS a ON a.APPLICATION_ID=l.APPLICATION_ID JOIN MFF_ORGANIZATIONS f ON f.ORG_ID=a.FINANCIER_ID;
